class Solution {
public:
    int findWinningPlayer(vector<int>& skills, int k) {
        int cur_winner = 0;
        int consecutive_wins = 0;
        int n = skills.size();
        for (int i = 1; i < n; ++i) {
            if (skills[cur_winner] > skills[i]) {
                consecutive_wins++;
            } else {
                cur_winner = i;
                consecutive_wins = 1;
            }
            if (consecutive_wins == k) return cur_winner;
        }
        return cur_winner;
    }
};

class Solution {
    public int findWinningPlayer(int[] skills, int k) {
