        int consecutiveWins = 0;
        int n = skills.length;
        for (int i = 1; i < n; ++i) {
            if (skills[curWinner] > skills[i]) {
                consecutiveWins++;
            } else {
                curWinner = i;
                consecutiveWins = 1;
            }
            if (consecutiveWins == k) return curWinner;
        }
        return curWinner;
    }
}

var findWinningPlayer = function(skills, k) {
    let curWinner = 0;
    let consecutiveWins = 0;
    const n = skills.length;
    for (let i = 1; i < n; ++i) {
        if (skills[curWinner] > skills[i]) {
            consecutiveWins++;
        } else {
            curWinner = i;
            consecutiveWins = 1;
        }
        if (consecutiveWins === k) return curWinner;
    }
    return curWinner;
};
